import json, subprocess, warnings
warnings.filterwarnings("ignore")
from TTS.utils.synthesizer import Synthesizer
from hts_close import close_voice
lines = [
 "बायोप्सी रिपोर्ट में लिखा है, आई एच सी की सलाह? घबराइए मत. आई एच सी मार्कर क्या हैं, और क्यों ज़रूरी हैं, आखिर तक देखिए.",
 "आई एच सी यानी इम्यूनोहिस्टोकेमिस्ट्री. माइक्रोस्कोप में कई बीमारियों की कोशिकाएं एक जैसी दिख सकती हैं. आई एच सी से पता चलता है कि कोशिका में कौन सा प्रोटीन है, और यह कोशिका असल में किस तरह की है.",
 "यह कैसे काम करता है? लैब में बने खास एंटीबॉडी, ताला चाबी की तरह, सिर्फ अपने प्रोटीन से चिपकते हैं. फिर एक रंग की प्रतिक्रिया होती है, और जहां वह प्रोटीन है, वह हिस्सा भूरे रंग का दिखता है. भूरा रंग, यानी पॉज़िटिव.",
 "क्या दोबारा सैंपल देना होगा? आमतौर पर नहीं. आई एच सी उसी बायोप्सी के मोम वाले ब्लॉक से किया जाता है. अगर बायोप्सी किसी और जगह हुई है, तो वहां से ब्लॉक या स्लाइड मंगवाई जाती है.",
 "आई एच सी किस काम आता है? पहला, सही पहचान. जैसे बीमारी किस तरह की कोशिका से है. फेफड़े के कैंसर में टी टी एफ वन, मेलानोमा में एस सौ. और लिम्फोमा में बी सेल और टी सेल अलग करने के लिए सी डी बीस और सी डी तीन.",
 "दूसरा, इलाज की दिशा. ब्रेस्ट कैंसर में ई आर, पी आर, और हर टू मार्कर देखे जाते हैं. अगर एक प्रतिशत से ज़्यादा कोशिकाएं ई आर या पी आर पॉज़िटिव हों, तो हार्मोन थेरेपी का विकल्प हो सकता है.",
 "हर टू का स्कोर ज़ीरो से थ्री प्लस तक होता है. थ्री प्लस यानी पॉज़िटिव. टू प्लस पर, फिश नाम की जीन जांच से आगे की पुष्टि हो सकती है. और वन प्लस, या टू प्लस के साथ फिश नेगेटिव को, हर टू लो कहते हैं.",
 "रिपोर्ट में हर मार्कर के आगे पॉज़िटिव या नेगेटिव लिखा होता है, कभी प्रतिशत और रंग की तीव्रता के साथ. आई एच सी में कुछ अतिरिक्त दिन लग सकते हैं. रिपोर्ट पैथोलॉजिस्ट बनाते हैं, और इलाज का फैसला आपके डॉक्टर करते हैं.",
 "याद रखिए, कोई एक मार्कर अकेले बीमारी तय नहीं करता. पैथोलॉजिस्ट कई मार्कर, और माइक्रोस्कोप की तस्वीर को साथ मिलाकर नतीजा देते हैं. इसलिए इंटरनेट पर अकेले किसी मार्कर का मतलब खोजकर परेशान न हों.",
 close_voice("क्या आपने कभी आई एच सी रिपोर्ट देखी है?"),
]
import os
d = os.environ.get("HTS_MODEL", "/tmp/hi/hi/")
s = Synthesizer(tts_checkpoint=d + "fastpitch/best_model.pth", tts_config_path=d + "fastpitch/config.json",
                vocoder_checkpoint=d + "hifigan/best_model.pth", vocoder_config=d + "hifigan/config.json", use_cuda=False)
durs = []
for i, l in enumerate(lines):
    f = f"/tmp/ihcr_{i}.wav"; s.save_wav(s.tts(l, speaker_name="female"), f)
    subprocess.run(["ffmpeg","-nostdin","-y","-loglevel","error","-i",f,"-af","rubberband=pitch=0.96:formant=preserved,equalizer=f=250:t=q:w=1:g=2,treble=g=-1.5:f=6000",f"/tmp/ihc_{i}.wav"],check=True); f=f"/tmp/ihc_{i}.wav"
    durs.append(float(subprocess.check_output(["ffprobe", "-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", f]).decode()))
json.dump(durs, open("/tmp/ihc_durs.json", "w")); print([round(x, 1) for x in durs], round(sum(durs), 1))
